// OptimizerServiceServer is the server API for OptimizerService service.
// All implementations must embed UnimplementedOptimizerServiceServer
// for forward compatibility.
type OptimizerServiceServer interface {
	CreateLineage(context.Context, *CreateLineageRequest) (*CreateLineageResponse, error)
	GetLineage(context.Context, *GetLineageRequest) (*GetLineageResponse, error)
	ListLineages(context.Context, *ListLineagesRequest) (*ListLineagesResponse, error)
	// Raising the level needs owner step-up; lowering is instant for anyone allowed (EX-033).
	SetLineageAutonomy(context.Context, *SetLineageAutonomyRequest) (*SetLineageAutonomyResponse, error)
	// Opens a research cycle with a MinBTL-derived effective-trial budget (D31 rule 3); owner only.
	OpenCycle(context.Context, *OpenCycleRequest) (*OpenCycleResponse, error)
	CreateStudy(context.Context, *CreateStudyRequest) (*CreateStudyResponse, error)
	StartStudy(context.Context, *StartStudyRequest) (*StartStudyResponse, error)
	PauseStudy(context.Context, *PauseStudyRequest) (*PauseStudyResponse, error)
	ResumeStudy(context.Context, *ResumeStudyRequest) (*ResumeStudyResponse, error)
	StopStudy(context.Context, *StopStudyRequest) (*StopStudyResponse, error)
	GetStudy(context.Context, *GetStudyRequest) (*GetStudyResponse, error)
	ListStudies(context.Context, *ListStudiesRequest) (*ListStudiesResponse, error)
	StreamStudyProgress(*StreamStudyProgressRequest, grpc.ServerStreamingServer[StreamStudyProgressResponse]) error
	ListTrials(context.Context, *ListTrialsRequest) (*ListTrialsResponse, error)
	// Records an externally run trial (a training run launched outside a study) in its lineage (EX-020).
	RecordTrial(context.Context, *RecordTrialRequest) (*RecordTrialResponse, error)
	// Diagnostics and analyst tools (holdout excluded by construction).
	GetStudyDiagnostics(context.Context, *GetStudyDiagnosticsRequest) (*GetStudyDiagnosticsResponse, error)
	GetTrialLedger(context.Context, *GetTrialLedgerRequest) (*GetTrialLedgerResponse, error)
	GetCumulativeOverfittingStats(context.Context, *GetCumulativeOverfittingStatsRequest) (*GetCumulativeOverfittingStatsResponse, error)
	// Analyst callers get an AnalystGateView-filtered report: no failure reasons or thresholds (EX-035).
	GetGateReport(context.Context, *GetGateReportRequest) (*GetGateReportResponse, error)
	GetWalkForwardBreakdown(context.Context, *GetWalkForwardBreakdownRequest) (*GetWalkForwardBreakdownResponse, error)
	GetRegimeBreakdown(context.Context, *GetRegimeBreakdownRequest) (*GetRegimeBreakdownResponse, error)
	GetCostSensitivity(context.Context, *GetCostSensitivityRequest) (*GetCostSensitivityResponse, error)
	ListCandidates(context.Context, *ListCandidatesRequest) (*ListCandidatesResponse, error)
	GetCandidate(context.Context, *GetCandidateRequest) (*GetCandidateResponse, error)
	// Dry run of the permission table and gates for (caller, candidate, to_stage) (EX-032).
	CheckTransition(context.Context, *CheckTransitionRequest) (*CheckTransitionResponse, error)
	// Requires gate checks; paper (new spec) and live_eligible require owner step-up (EX-051..EX-054).
	PromoteCandidate(context.Context, *PromoteCandidateRequest) (*PromoteCandidateResponse, error)
	DeployChallengerShadow(context.Context, *DeployChallengerShadowRequest) (*DeployChallengerShadowResponse, error)
	// Notifies the owner; never changes a stage (EX-034).
	NominateLiveEligible(context.Context, *NominateLiveEligibleRequest) (*NominateLiveEligibleResponse, error)
	// Monitoring demotion input (section 13): moves to paper or retired; re-promotion is manual (EX-055).
	DemoteCandidate(context.Context, *DemoteCandidateRequest) (*DemoteCandidateResponse, error)
	GetEvidencePack(context.Context, *GetEvidencePackRequest) (*GetEvidencePackResponse, error)
	GetLineageGraph(context.Context, *GetLineageGraphRequest) (*GetLineageGraphResponse, error)
	SetRetrainingPolicy(context.Context, *SetRetrainingPolicyRequest) (*SetRetrainingPolicyResponse, error)
	TriggerRetrain(context.Context, *TriggerRetrainRequest) (*TriggerRetrainResponse, error)
	// Candidate deployment limits (EX-062, ADR-0047): the risk limits and allocation a lineage's
	// candidates are judged under in the event-driven gate rerun and registered with in execution.
	GetDeploymentLimits(context.Context, *GetDeploymentLimitsRequest) (*GetDeploymentLimitsResponse, error)
	// Owner only; raising any limit above the lineage's current effective limits needs a passkey
	// step-up (RM-007). The analyst is denied at every level.
	SetDeploymentLimits(context.Context, *SetDeploymentLimitsRequest) (*SetDeploymentLimitsResponse, error)
	// Research-side inputs of the section 15 graduation report (GL-002, ADR-0054): the strategy's
	// registry stage, DSR on the combined research + paper record (lineage effective N, D31 rule 2),
	// the backtest's horizon-matched 95th-percentile drawdown, the modeled shortfall, and the latest
	// live-vs-backtest divergence. Callers: api-gateway, execution. Never the assistant.
	GetGraduationStatistics(context.Context, *GetGraduationStatisticsRequest) (*GetGraduationStatisticsResponse, error)
	mustEmbedUnimplementedOptimizerServiceServer()
}

